  "quiz": [
    {
      "id": "q1",
      "q": "戚寒衣的父亲是谁？",
      "options": [
        {
          "key": "A",
          "text": "青冥宗的先宗主戚长庚"
        },
        {
          "key": "B",
          "text": "落霞谷的山民"
        },
        {
          "key": "C",
          "text": "山下甄家的家主"
        },
        {
          "key": "D",
          "text": "藏经阁的上一任管事"
        }
      ],
      "answer": "A",
      "clue": "hd_qi_4",
      "explain": "藏经阁《青冥宗志》夹页里的小像，题着「长庚与寒衣」：画中的中年道人就是先宗主戚长庚，牵着的小姑娘是戚寒衣。"
    },
    {
      "id": "q2",
      "q": "二十年前那个中元夜，先宗主的魂灯是什么时候熄的？",
      "options": [
        {
          "key": "A",
          "text": "狐妖袭山之后"
        },
        {
          "key": "B",
          "text": "狐妖袭山之前"
        },
        {
          "key": "C",
          "text": "第二天天亮以后"
        },
        {
          "key": "D",
          "text": "先宗主闭关的那一天"
        }
      ],
      "answer": "B",
      "clue": "hd_zh_3",
      "explain": "张守灯床脚藏着的守灯簿原页写着：戌时三刻，先宗主灯熄；子时，狐袭山门。灯先熄，狐后到。官簿上那一行的时辰被刀刮过，改成了子时。"
    },
    {
      "id": "q3",
      "q": "鬼灵儿出自哪里？",
      "options": [
        {
          "key": "A",
          "text": "灵兽园里出生"
        },
        {
          "key": "B",
          "text": "山下猎户的狐场"
        },
        {
          "key": "C",
          "text": "落霞谷青丘狐族"
        },
        {
          "key": "D",
          "text": "后山寒潭"
        }
      ],
      "answer": "C",
      "clue": "hd_gui_4",
      "explain": "鬼灵儿的狐皮襁褓内侧用金线绣着「落霞谷青丘」，她是二十年前从落霞谷带回来的白狐崽。"
    },
    {
      "id": "q4",
      "q": "欧采薇的道侣撒青川，当年在宗主手下做过什么？",
      "options": [
        {
          "key": "A",
          "text": "押送灵石下山"
        },
        {
          "key": "B",
          "text": "替宗主试丹"
        },
        {
          "key": "C",
          "text": "看守魂灯殿"
        },
        {
          "key": "D",
          "text": "修补藏经阁的古籍"
        }
      ],
      "answer": "B",
      "clue": "hd_ou_4",
      "explain": "欧采薇暗格里那页宗主亲笔的丹方，页角写着「青川试丹，第七日」。"
    },
    {
      "id": "q5",
      "q": "正殿西壁的旧碑上，宗门对外是怎么交代先宗主之事的？",
      "options": [
        {
          "key": "A",
          "text": "闭关时走火入魔"
        },
        {
          "key": "B",
          "text": "下山云游未归"
        },
        {
          "key": "C",
          "text": "狐妖夜袭山门，力战而亡"
        },
        {
          "key": "D",
          "text": "寿元耗尽，坐化于静室"
        }
      ],
      "answer": "C",
      "clue": "hd_zd_4",
      "explain": "西壁旧碑记的是：狐妖夜袭山门，先宗主戚长庚力战而亡，甄无涯率众荡平落霞谷。"
    },
    {
      "id": "q6",
      "q": "甄无涯当年结成金丹的那张丹方，用的引子是什么？",
      "options": [
        {
          "key": "A",
          "text": "寒玉髓"
        },
        {
          "key": "B",
          "text": "千年灵芝"
        },
        {
          "key": "C",
          "text": "青丘狐丹"
        },
        {
          "key": "D",
          "text": "魂灯灯油"
        }
      ],
      "answer": "C",
      "clue": "hd_ou_4",
      "explain": "丹方题为「凝金丹·以青丘狐丹为引」：落霞谷一役之后，他靠青丘狐的内丹结了金丹。"
    }
  ],
